<?php

/* @autogenerated */
declare(strict_types=1);

namespace Tests\integration\Features\OAuth\MagicLink;

use DateTimeImmutable;
use Nimbly\Capsule\Response;
use PHPUnit\Framework\MockObject\Stub;
use Civi\Lughauth\Features\Access\Tenant\Domain\Tenant;
use Civi\Lughauth\Features\Access\Tenant\Domain\Gateway\TenantReadGateway;
use Civi\Lughauth\Features\Access\User\Domain\User;
use Civi\Lughauth\Features\Access\User\Domain\Gateway\UserReadGateway;
use Civi\Lughauth\Features\OAuth\MagicLink\Application\Usecase\RequestMagicLink\RequestMagicLinkUsecase;
use Civi\Lughauth\Features\OAuth\MagicLink\Application\Usecase\VerifyMagicLink\VerifyMagicLinkUsecase;
use Civi\Lughauth\Features\OAuth\MagicLink\Domain\MagicLink;
use Civi\Lughauth\Features\OAuth\MagicLink\Infrastructure\Driven\MagicLinkCodeAdapter;
use Civi\Lughauth\Features\OAuth\MagicLink\Infrastructure\Driver\Html\MagicLinkVerifyHtml;
use Civi\Lughauth\Features\OAuth\MagicLink\Infrastructure\Driver\Rest\MagicLinkRequestController;
use Civi\Lughauth\Features\OAuth\Theme\Application\DecorateHtml;
use Tests\integration\Features\OAuth\OidcIntegrationTestCase;
use Tests\integration\Features\OAuth\Stub\InMemoryMagicLinkEnabledGateway;
use Tests\integration\Features\OAuth\Stub\InMemoryMagicLinkGateway;
use Tests\integration\Features\OAuth\Stub\InMemoryMagicLinkMailGateway;
use Tests\integration\Features\OAuth\Stub\InMemoryMagicLinkSessionGateway;

class MagicLinkIntegrationTest extends OidcIntegrationTestCase
{
    private const string USER_EMAIL = 'magicuser@example.com';
    private const string REDIRECT_URI = 'https://app.example.com/callback';
    private const string BASE_URL = 'https://auth.example.com';

    private InMemoryMagicLinkGateway $magicLinkGateway;
    private InMemoryMagicLinkMailGateway $mailGateway;
    private InMemoryMagicLinkEnabledGateway $enabledGateway;
    private MagicLinkRequestController $requestController;
    private MagicLinkVerifyHtml $verifyController;

    /** @var Stub&TenantReadGateway */
    private TenantReadGateway $tenantGateway;

    /** @var Stub&UserReadGateway */
    private UserReadGateway $userGateway;

    protected function setUp(): void
    {
        parent::setUp();

        $this->magicLinkGateway = new InMemoryMagicLinkGateway();
        $this->mailGateway = new InMemoryMagicLinkMailGateway();
        $this->enabledGateway = new InMemoryMagicLinkEnabledGateway();
        $this->enabledGateway->enable(self::TENANT);

        $user = $this->createStub(User::class);
        $user->method('uid')->willReturn(self::USER_ID);
        $user->method('isEnabled')->willReturn(true);
        $user->method('getName')->willReturn('Magic User');

        $tenant = $this->createStub(Tenant::class);
        $tenant->method('uid')->willReturn('tenant-uid-1');
        $tenant->method('isEnabled')->willReturn(true);

        $this->userGateway = $this->createStub(UserReadGateway::class);
        $this->userGateway->method('findOneByTenantAndName')->willReturn($user);
        $this->userGateway->method('findOneByUid')->willReturn($user);

        $this->tenantGateway = $this->createStub(TenantReadGateway::class);
        $this->tenantGateway->method('findOneByName')->willReturn($tenant);

        $requestUsecase = new RequestMagicLinkUsecase(
            users: $this->userGateway,
            tenants: $this->tenantGateway,
            clients: $this->clientStore,
            gateway: $this->magicLinkGateway,
            mailer: $this->mailGateway,
            enabled: $this->enabledGateway,
            baseUrl: self::BASE_URL,
        );

        $codeGateway = new MagicLinkCodeAdapter(
            loginGateway: $this->loginGateway,
            clientStore: $this->clientStore,
            temporalKeys: $this->temporalKeys,
        );

        $verifyUsecase = new VerifyMagicLinkUsecase(
            gateway: $this->magicLinkGateway,
            codeGateway: $codeGateway,
            enabled: $this->enabledGateway,
            sessionGateway: new InMemoryMagicLinkSessionGateway(),
            tenants: $this->tenantGateway,
            users: $this->userGateway,
        );

        $decorator = $this->createStub(DecorateHtml::class);
        $decorator->method('getFullPage')->willReturn('<html>error</html>');

        $cookies = $this->createStub(\Civi\Lughauth\Features\OAuth\Authentication\Infrastructure\Driver\Html\Services\OidcCookieManager::class);
        $cookies->method('authenticatedSessionCookie')->willReturn(
            new \Civi\Lughauth\Shared\Infrastructure\Http\Cookie(name: 'AUTH_SESSION_ID_TENANT1', value: 'session-id', expiration: new \DateInterval('P15D'))
        );

        $this->requestController = new MagicLinkRequestController($requestUsecase);
        $this->verifyController = new MagicLinkVerifyHtml($verifyUsecase, $decorator, $cookies);
    }

    // --- REQUEST endpoint ---

    public function testRequestAlwaysReturns202ForValidEmail(): void
    {
        $request = $this->makeRequest('POST', '/oauth/openid/tenant1/magic-link/request', [
            'email' => self::USER_EMAIL,
            'client_id' => self::CLIENT_ID,
            'redirect_uri' => self::REDIRECT_URI,
        ]);

        $response = $this->requestController->request($request, new Response(200), ['tenant' => self::TENANT]);

        $this->assertSame(202, $response->getStatusCode());
    }

    public function testRequestStoresMagicLinkAndSendsEmail(): void
    {
        $request = $this->makeRequest('POST', '/oauth/openid/tenant1/magic-link/request', [
            'email' => self::USER_EMAIL,
            'client_id' => self::CLIENT_ID,
            'redirect_uri' => self::REDIRECT_URI,
        ]);

        $this->requestController->request($request, new Response(200), ['tenant' => self::TENANT]);

        $this->assertSame(1, $this->mailGateway->count());
        $this->assertSame(self::USER_EMAIL, $this->mailGateway->sent[0]['email']);
        $this->assertStringContainsString('/magic-link/verify', $this->mailGateway->lastUrl());
        $this->assertStringContainsString('token=', $this->mailGateway->lastUrl());

        $storedLink = $this->magicLinkGateway->last();
        $this->assertNotNull($storedLink);
        $this->assertSame(self::TENANT, $storedLink->tenantId);
        $this->assertSame(self::CLIENT_ID, $storedLink->clientId);
    }

    public function testRequestReturns202EvenForUnknownEmail(): void
    {
        $this->userGateway = $this->createStub(UserReadGateway::class);
        $this->userGateway->method('findOneByTenantAndName')->willReturn(null);

        $requestUsecase = new RequestMagicLinkUsecase(
            users: $this->userGateway,
            tenants: $this->tenantGateway,
            clients: $this->clientStore,
            gateway: $this->magicLinkGateway,
            mailer: $this->mailGateway,
            enabled: $this->enabledGateway,
            baseUrl: self::BASE_URL,
        );
        $controller = new MagicLinkRequestController($requestUsecase);

        $request = $this->makeRequest('POST', '/oauth/openid/tenant1/magic-link/request', [
            'email' => 'nobody@example.com',
            'client_id' => self::CLIENT_ID,
            'redirect_uri' => self::REDIRECT_URI,
        ]);

        $response = $controller->request($request, new Response(200), ['tenant' => self::TENANT]);

        $this->assertSame(202, $response->getStatusCode());
        $this->assertSame(0, $this->mailGateway->count());
        $this->assertNull($this->magicLinkGateway->last());
    }

    public function testRequestReturns202WhenParamsMissing(): void
    {
        $request = $this->makeRequest('POST', '/oauth/openid/tenant1/magic-link/request', [
            'email' => self::USER_EMAIL,
            // missing client_id and redirect_uri
        ]);

        $response = $this->requestController->request($request, new Response(200), ['tenant' => self::TENANT]);

        $this->assertSame(202, $response->getStatusCode());
        $this->assertSame(0, $this->mailGateway->count());
    }

    // --- VERIFY endpoint ---

    public function testVerifyValidTokenRedirectsWithCode(): void
    {
        $rawToken = $this->storeMagicLink();

        $request = $this->makeRequest('GET', '/oauth/openid/tenant1/magic-link/verify');
        $request = $request->withQueryParams(['token' => $rawToken, 'client_id' => self::CLIENT_ID]);

        $response = $this->verifyController->verify($request, new Response(200), ['tenant' => self::TENANT]);

        $this->assertSame(302, $response->getStatusCode());
        $location = $response->getHeaderLine('Location');
        $this->assertStringStartsWith(self::REDIRECT_URI, $location);
        $this->assertStringContainsString('code=', $location);
    }

    public function testVerifyValidTokenWithStateIncludesStateInRedirect(): void
    {
        $rawToken = $this->storeMagicLink(state: 'my-state-xyz');

        $request = $this->makeRequest('GET', '/oauth/openid/tenant1/magic-link/verify');
        $request = $request->withQueryParams(['token' => $rawToken, 'client_id' => self::CLIENT_ID]);

        $response = $this->verifyController->verify($request, new Response(200), ['tenant' => self::TENANT]);

        $this->assertSame(302, $response->getStatusCode());
        $this->assertStringContainsString('state=my-state-xyz', $response->getHeaderLine('Location'));
    }

    public function testVerifyExpiredTokenReturns400(): void
    {
        $rawToken = bin2hex(random_bytes(32));
        $link = MagicLink::create(
            uid: 'test-uid',
            tenantId: self::TENANT,
            userUid: self::USER_ID,
            clientId: self::CLIENT_ID,
            tokenHash: hash('sha256', $rawToken),
            redirectUri: self::REDIRECT_URI,
            scope: 'openid email',
            state: null,
            expiresAt: new DateTimeImmutable('-1 hour'),
        );
        $this->magicLinkGateway->store($link);

        $request = $this->makeRequest('GET', '/oauth/openid/tenant1/magic-link/verify');
        $request = $request->withQueryParams(['token' => $rawToken, 'client_id' => self::CLIENT_ID]);

        $response = $this->verifyController->verify($request, new Response(200), ['tenant' => self::TENANT]);

        $this->assertSame(400, $response->getStatusCode());
    }

    public function testVerifyAlreadyUsedTokenReturns400(): void
    {
        $rawToken = $this->storeMagicLink();

        $request = $this->makeRequest('GET', '/oauth/openid/tenant1/magic-link/verify');
        $request = $request->withQueryParams(['token' => $rawToken, 'client_id' => self::CLIENT_ID]);

        // First use — valid
        $first = $this->verifyController->verify($request, new Response(200), ['tenant' => self::TENANT]);
        $this->assertSame(302, $first->getStatusCode());

        // Second use — must fail
        $second = $this->verifyController->verify($request, new Response(200), ['tenant' => self::TENANT]);
        $this->assertSame(400, $second->getStatusCode());
    }

    public function testVerifyWrongClientIdReturns400(): void
    {
        $rawToken = $this->storeMagicLink();

        $request = $this->makeRequest('GET', '/oauth/openid/tenant1/magic-link/verify');
        $request = $request->withQueryParams(['token' => $rawToken, 'client_id' => 'wrong-client']);

        $response = $this->verifyController->verify($request, new Response(200), ['tenant' => self::TENANT]);

        $this->assertSame(400, $response->getStatusCode());
    }

    public function testVerifyUnknownTokenReturns400(): void
    {
        $request = $this->makeRequest('GET', '/oauth/openid/tenant1/magic-link/verify');
        $request = $request->withQueryParams(['token' => bin2hex(random_bytes(32)), 'client_id' => self::CLIENT_ID]);

        $response = $this->verifyController->verify($request, new Response(200), ['tenant' => self::TENANT]);

        $this->assertSame(400, $response->getStatusCode());
    }

    public function testVerifyMissingParamsReturns400(): void
    {
        $request = $this->makeRequest('GET', '/oauth/openid/tenant1/magic-link/verify');

        $response = $this->verifyController->verify($request, new Response(200), ['tenant' => self::TENANT]);

        $this->assertSame(400, $response->getStatusCode());
    }

    // --- Full flow ---

    public function testFullFlow(): void
    {
        // 1. Request magic link
        $postRequest = $this->makeRequest('POST', '/oauth/openid/tenant1/magic-link/request', [
            'email' => self::USER_EMAIL,
            'client_id' => self::CLIENT_ID,
            'redirect_uri' => self::REDIRECT_URI,
        ]);
        $postResponse = $this->requestController->request($postRequest, new Response(200), ['tenant' => self::TENANT]);
        $this->assertSame(202, $postResponse->getStatusCode());

        // 2. Extract raw token from the magic URL sent by email
        $magicUrl = $this->mailGateway->lastUrl();
        $this->assertNotNull($magicUrl);
        parse_str((string) parse_url($magicUrl, PHP_URL_QUERY), $queryParams);
        $rawToken = $queryParams['token'];
        $this->assertNotEmpty($rawToken);

        // 3. Verify the token
        $getRequest = $this->makeRequest('GET', '/oauth/openid/tenant1/magic-link/verify');
        $getRequest = $getRequest->withQueryParams(['token' => $rawToken, 'client_id' => self::CLIENT_ID]);
        $getResponse = $this->verifyController->verify($getRequest, new Response(200), ['tenant' => self::TENANT]);

        $this->assertSame(302, $getResponse->getStatusCode());
        $location = $getResponse->getHeaderLine('Location');
        $this->assertStringStartsWith(self::REDIRECT_URI . '?code=', $location);
    }

    // --- Enabled flag ---

    public function testRequestReturns202ButSendsNoEmailWhenDisabled(): void
    {
        $this->enabledGateway->disable(self::TENANT);

        $request = $this->makeRequest('POST', '/oauth/openid/tenant1/magic-link/request', [
            'email' => self::USER_EMAIL,
            'client_id' => self::CLIENT_ID,
            'redirect_uri' => self::REDIRECT_URI,
        ]);

        $response = $this->requestController->request($request, new Response(200), ['tenant' => self::TENANT]);

        $this->assertSame(202, $response->getStatusCode());
        $this->assertSame(0, $this->mailGateway->count());
        $this->assertNull($this->magicLinkGateway->last());
    }

    public function testVerifyReturns400WhenDisabled(): void
    {
        $rawToken = $this->storeMagicLink();
        $this->enabledGateway->disable(self::TENANT);

        $request = $this->makeRequest('GET', '/oauth/openid/tenant1/magic-link/verify');
        $request = $request->withQueryParams(['token' => $rawToken, 'client_id' => self::CLIENT_ID]);

        $response = $this->verifyController->verify($request, new Response(200), ['tenant' => self::TENANT]);

        $this->assertSame(400, $response->getStatusCode());
    }

    public function testIsEnabledReflectsFlag(): void
    {
        $requestUsecase = new \Civi\Lughauth\Features\OAuth\MagicLink\Application\Usecase\RequestMagicLink\RequestMagicLinkUsecase(
            users: $this->userGateway,
            tenants: $this->tenantGateway,
            clients: $this->clientStore,
            gateway: $this->magicLinkGateway,
            mailer: $this->mailGateway,
            enabled: $this->enabledGateway,
            baseUrl: self::BASE_URL,
        );

        $this->assertTrue($requestUsecase->isEnabled(self::TENANT));

        $this->enabledGateway->disable(self::TENANT);
        $this->assertFalse($requestUsecase->isEnabled(self::TENANT));
    }

    // --- Helpers ---

    private function storeMagicLink(?string $state = null): string
    {
        $rawToken = bin2hex(random_bytes(32));
        $link = MagicLink::create(
            uid: 'test-uid-' . uniqid(),
            tenantId: self::TENANT,
            userUid: self::USER_ID,
            clientId: self::CLIENT_ID,
            tokenHash: hash('sha256', $rawToken),
            redirectUri: self::REDIRECT_URI,
            scope: 'openid email',
            state: $state,
            expiresAt: new DateTimeImmutable('+15 minutes'),
        );
        $this->magicLinkGateway->store($link);
        return $rawToken;
    }
}
